#![allow(clippy::inline_always, clippy::ref_as_ptr, reason = "code generated by windows_core::implement")]

use windows::{
    Win32::Media::{
        KernelStreaming::{PROPSETID_VIDCAP_CAMERACONTROL, PROPSETID_VIDCAP_VIDEOPROCAMP},
        MediaFoundation::{
            IMFCameraControlMonitor, IMFCameraControlNotify, IMFCameraControlNotify_Impl,
            IMFSensorActivitiesReport, IMFSensorActivitiesReportCallback,
            IMFSensorActivitiesReportCallback_Impl, IMFSensorActivityMonitor, IMFSensorActivityReport,
            MFCreateCameraControlMonitor, MFCreateSensorActivityMonitor,
        },
    },
    core::{GUID, HRESULT, HSTRING, Ref},
};
use windows_core::implement;

use webca_core::{ControlId, DeviceError};

use crate::{
    error::platform_error,
    mapping::{self, Location},
};

/// Which processes stream from one camera, as reported by Windows.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ActivityReport {
    pub device_path: String,
    pub streaming_processes: Vec<u32>,
}

type ActivityHandler = Box<dyn Fn(ActivityReport) + Send + Sync>;
type ControlHandler = Box<dyn Fn(ControlId) + Send + Sync>;

#[implement(IMFSensorActivitiesReportCallback)]
struct ActivityCallback {
    handler: ActivityHandler,
}

impl IMFSensorActivitiesReportCallback_Impl for ActivityCallback_Impl {
    fn OnActivitiesReport(&self, report: Ref<IMFSensorActivitiesReport>) -> windows::core::Result<()> {
        let report = report.ok()?;
        // SAFETY: `report` is a live report passed by Media Foundation for the duration of the call.
        let count = unsafe { report.GetCount()? };
        for index in 0..count {
            // SAFETY: `index` is below the reported count.
            let device = unsafe { report.GetActivityReport(index)? };
            (self.handler)(read_device(&device)?);
        }
        Ok(())
    }
}

fn read_device(device: &IMFSensorActivityReport) -> windows::core::Result<ActivityReport> {
    let mut buffer = [0u16; 512];
    let mut written = 0u32;
    // SAFETY: the buffer and counter are valid locals.
    unsafe { device.GetSymbolicLink(&mut buffer, &raw mut written)? };
    let length = buffer.iter().position(|&unit| unit == 0).unwrap_or(buffer.len());
    let device_path = String::from_utf16_lossy(&buffer[..length]).to_lowercase();
    let mut streaming_processes = Vec::new();
    // SAFETY: reading counts and entries of a live report.
    for index in 0..unsafe { device.GetProcessCount()? } {
        let process = unsafe { device.GetProcessActivity(index)? };
        if unsafe { process.GetStreamingState()? }.as_bool() {
            streaming_processes.push(unsafe { process.GetProcessId()? });
        }
    }
    Ok(ActivityReport { device_path, streaming_processes })
}

/// Reports whenever any process starts or stops streaming from any camera; stops when dropped.
#[derive(Debug)]
pub struct ActivityMonitor {
    monitor: IMFSensorActivityMonitor,
}

impl ActivityMonitor {
    pub fn start(handler: impl Fn(ActivityReport) + Send + Sync + 'static) -> Result<Self, DeviceError> {
        let callback: IMFSensorActivitiesReportCallback =
            ActivityCallback { handler: Box::new(handler) }.into();
        // SAFETY: the callback is a valid COM object kept alive by the monitor.
        let monitor =
            unsafe { MFCreateSensorActivityMonitor(&callback) }.map_err(|error| platform_error(&error))?;
        // SAFETY: starting a freshly created monitor.
        unsafe { monitor.Start() }.map_err(|error| platform_error(&error))?;
        Ok(Self { monitor })
    }
}

impl Drop for ActivityMonitor {
    fn drop(&mut self) {
        // SAFETY: stopping a monitor we started; failure leaves nothing to clean up.
        let _ = unsafe { self.monitor.Stop() };
    }
}

#[implement(IMFCameraControlNotify)]
struct ControlCallback {
    handler: ControlHandler,
}

impl IMFCameraControlNotify_Impl for ControlCallback_Impl {
    fn OnChange(&self, control_set: *const GUID, id: u32) {
        // SAFETY: Media Foundation passes a valid GUID pointer for the duration of the call.
        let Some(set) = (unsafe { control_set.as_ref() }) else { return };
        if let Some(control) = location_of(*set, id).and_then(mapping::identify) {
            (self.handler)(control);
        }
    }

    fn OnError(&self, _status: HRESULT) {}
}

fn location_of(set: GUID, id: u32) -> Option<Location> {
    let id = id.cast_signed();
    match set {
        PROPSETID_VIDCAP_VIDEOPROCAMP => Some(Location::ProcAmp(id)),
        PROPSETID_VIDCAP_CAMERACONTROL => Some(Location::CameraControl(id)),
        _ => None,
    }
}

/// Reports changes to the given controls of one camera, by any process; stops when dropped.
#[derive(Debug)]
pub struct ControlMonitor {
    monitor: IMFCameraControlMonitor,
}

impl ControlMonitor {
    pub fn start(
        device_path: &str,
        controls: &[ControlId],
        handler: impl Fn(ControlId) + Send + Sync + 'static,
    ) -> Result<Self, DeviceError> {
        let callback: IMFCameraControlNotify = ControlCallback { handler: Box::new(handler) }.into();
        let path = HSTRING::from(device_path);
        // SAFETY: the path is a NUL-terminated HSTRING and the callback a valid COM object.
        let monitor = unsafe { MFCreateCameraControlMonitor(&path, &callback) }
            .map_err(|error| platform_error(&error))?;
        for control in controls {
            let (set, id) = match mapping::locate(*control) {
                Location::ProcAmp(id) => (PROPSETID_VIDCAP_VIDEOPROCAMP, id.unsigned_abs()),
                Location::CameraControl(id) => (PROPSETID_VIDCAP_CAMERACONTROL, id.unsigned_abs()),
            };
            // SAFETY: subscribing before Start, as the API requires.
            unsafe { monitor.AddControlSubscription(set, id) }.map_err(|error| platform_error(&error))?;
        }
        // SAFETY: starting a configured monitor.
        unsafe { monitor.Start() }.map_err(|error| platform_error(&error))?;
        Ok(Self { monitor })
    }
}

impl Drop for ControlMonitor {
    fn drop(&mut self) {
        // SAFETY: stopping and shutting down a monitor we own; no calls follow.
        unsafe {
            let _ = self.monitor.Stop();
            self.monitor.Shutdown();
        }
    }
}
